import java.util.*;

class mcf_graph_int_cost {
    int n;
    ArrayList<int[]> pos;
    ArrayList<ArrayList<_Edge>> g;
    long[] dual;
    long[] dist;
    int[] pv;
    int[] pe;
    boolean[] vis;

    mcf_graph_int_cost(int n) {
        this.n = n;
        pos = new ArrayList<>();
        g = new ArrayList<>(n);
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
    }

    static class _Edge {
        int to, rev;
        long cap, cost;
        _Edge(int to, int rev, long cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class Edge {
        int from, to;
        long cap, flow, cost;
        Edge(int from, int to, long cap, long flow, long cost) {
            this.from = from;
            this.to = to;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    int add_edge(int from, int to, long cap, long cost) {
        int m = pos.size();
        pos.add(new int[]{from, g.get(from).size()});
        g.get(from).add(new _Edge(to, g.get(to).size(), cap, cost));
        g.get(to).add(new _Edge(from, g.get(from).size() - 1, 0, -cost));
        return m;
    }

    Edge get_edge(int i) {
        int[] p = pos.get(i);
        _Edge e = g.get(p[0]).get(p[1]);
        _Edge re = g.get(e.to).get(e.rev);
        return new Edge(p[0], e.to, e.cap + re.cap, re.cap, e.cost);
    }

    ArrayList<Edge> edges() {
        ArrayList<Edge> res = new ArrayList<>();
        for (int i = 0; i < pos.size(); i++) res.add(get_edge(i));
        return res;
    }

    boolean _dual_ref(int s, int t) {
        long LARGE = (1L << 32) - 1;
        Arrays.fill(dist, LARGE);
        Arrays.fill(pv, -1);
        Arrays.fill(pe, -1);
        Arrays.fill(vis, false);
        PriorityQueue<Long> pq = new PriorityQueue<>();
        dist[s] = 0;
        pq.offer((long) s);
        while (!pq.isEmpty()) {
            long key = pq.poll();
            int v = (int) (key & 0xFFFFFFFFL);
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < g.get(v).size(); i++) {
                _Edge e = g.get(v).get(i);
                if (vis[e.to] || e.cap == 0) continue;
                long cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    long newKey = (dist[e.to] << 32) | (e.to & 0xFFFFFFFFL);
                    pq.offer(newKey);
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; v++) {
            if (vis[v]) dual[v] -= dist[t] - dist[v];
        }
        return true;
    }

    ArrayList<long[]> slope(int s, int t, long flow_limit) {
        long LARGE = (1L << 32) - 1;
        dual = new long[n];
        dist = new long[n];
        pv = new int[n];
        pe = new int[n];
        vis = new boolean[n];
        long flow = 0, cost = 0, prev_cost = -1;
        ArrayList<long[]> result = new ArrayList<>();
        result.add(new long[]{flow, cost});
        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;
            long c = flow_limit - flow;
            int v = t;
            while (v != s) {
                _Edge e = g.get(pv[v]).get(pe[v]);
                c = Math.min(c, e.cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                _Edge e = g.get(pv[v]).get(pe[v]);
                e.cap -= c;
                _Edge re = g.get(v).get(e.rev);
                re.cap += c;
                v = pv[v];
            }
            long d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) result.remove(result.size() - 1);
            result.add(new long[]{flow, cost});
            prev_cost = cost;
        }
        return result;
    }

    long[] flow(int s, int t, long flow_limit) {
        ArrayList<long[]> slopes = slope(s, t, flow_limit);
        return slopes.get(slopes.size() - 1);
    }

    long[] flow(int s, int t) {
        return flow(s, t, (1L << 32) - 1);
    }
}

public class Main {
    static final long INF = 1_000_000_000L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long a1 = sc.nextLong(), a2 = sc.nextLong(), a3 = sc.nextLong();
        long b1 = sc.nextLong(), b2 = sc.nextLong(), b3 = sc.nextLong();

        mcf_graph_int_cost g = new mcf_graph_int_cost(8);
        g.add_edge(0, 1, a1, 0);
        g.add_edge(0, 2, a2, 0);
        g.add_edge(0, 3, a3, 0);
        g.add_edge(4, 7, b1, 0);
        g.add_edge(5, 7, b2, 0);
        g.add_edge(6, 7, b3, 0);
        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                long cost = ((j - i) % 3 == 1) ? 1 : 0;
                g.add_edge(i, j, INF, cost);
            }
        }

        long[] result = g.flow(0, 7);
        long ans1 = result[1]; // cost
        long ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}

import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final long MOD = 998244353L;
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    static int[] li() throws IOException {
        String[] parts = br.readLine().trim().split("\\s+");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }

    static String st() throws IOException {
        return br.readLine();
    }

    static int val() throws IOException {
        return Integer.parseInt(br.readLine().trim());
    }

    static long powMod(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long invMod(long n) {
        return powMod(n, MOD - 2);
    }

    static List<Integer> factors(int n) {
        List<Integer> res = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                res.add(i);
                if (i != n / i) {
                    res.add(n / i);
                }
            }
        }
        Collections.sort(res);
        return res;
    }

    static int match(int a, int b) {
        if (a == b) return 0;
        if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) return 1;
        return -1;
    }

    static int give(List<int[]> l1, List<int[]> l2) {
        int ans = 0;
        int[] curr1 = null;
        int[] curr2 = null;
        int idx1 = l1.size() - 1;
        int idx2 = l2.size() - 1;

        while (idx1 >= 0 || idx2 >= 0) {
            if (curr1 == null) {
                if (idx1 < 0) break;
                curr1 = l1.get(idx1--);
            }
            if (curr2 == null) {
                if (idx2 < 0) break;
                curr2 = l2.get(idx2--);
            }

            int p = Math.min(curr1[0], curr2[0]);
            int m = match(curr1[1], curr2[1]);
            if (m > 0) {
                ans += p * m;
            }

            if (curr1[0] < curr2[0]) {
                curr2[0] -= curr1[0];
                curr1 = null;
            } else if (curr1[0] > curr2[0]) {
                curr1[0] -= curr2[0];
                curr2 = null;
            } else {
                curr1 = null;
                curr2 = null;
            }
        }
        return ans;
    }

    static int maximum(int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        return Math.min(rock1, sci2) + Math.min(sci1, paper2) + Math.min(paper1, rock2);
    }

    static int minimum(int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        int n = rock1 + sci1 + paper1;
        int ans = Integer.MAX_VALUE;
        List<int[]> base1 = new ArrayList<>();
        base1.add(new int[]{rock1, 1});
        base1.add(new int[]{sci1, 2});
        base1.add(new int[]{paper1, 3});
        List<int[]> base2 = new ArrayList<>();
        base2.add(new int[]{rock2, 1});
        base2.add(new int[]{sci2, 2});
        base2.add(new int[]{paper2, 3});

        // Generate all permutations of base1
        List<List<int[]>> perms1 = new ArrayList<>();
        permute(base1, 0, perms1);
        List<List<int[]>> perms2 = new ArrayList<>();
        permute(base2, 0, perms2);

        for (List<int[]> perm1 : perms1) {
            for (List<int[]> perm2 : perms2) {
                List<int[]> copy1 = new ArrayList<>();
                for (int[] arr : perm1) copy1.add(arr.clone());
                List<int[]> copy2 = new ArrayList<>();
                for (int[] arr : perm2) copy2.add(arr.clone());
                ans = Math.min(ans, give(copy1, copy2));
            }
        }
        return ans;
    }

    static void permute(List<int[]> arr, int k, List<List<int[]>> result) {
        if (k == arr.size()) {
            result.add(new ArrayList<>(arr));
            return;
        }
        for (int i = k; i < arr.size(); i++) {
            Collections.swap(arr, k, i);
            permute(arr, k + 1, result);
            Collections.swap(arr, k, i);
        }
    }

    public static void main(String[] args) throws IOException {
        int n = val();
        int[] items = li();
        int rock1 = items[0], sci1 = items[1], paper1 = items[2];
        items = li();
        int rock2 = items[0], sci2 = items[1], paper2 = items[2];

        int min = minimum(rock1, sci1, paper1, rock2, sci2, paper2);
        int max = maximum(rock1, sci1, paper1, rock2, sci2, paper2);
        System.out.println(min + " " + max);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        String[] partsA = sc.nextLine().trim().split(" ");
        String[] partsB = sc.nextLine().trim().split(" ");
        int[] inputA = new int[3];
        int[] inputB = new int[3];
        for (int i = 0; i < 3; i++) {
            inputA[i] = Integer.parseInt(partsA[i]);
            inputB[i] = Integer.parseInt(partsB[i]);
        }
        int[] inputA2 = inputA.clone();
        int[] inputB2 = inputB.clone();
        int minWins = getWonMaxFast(inputA, inputB);
        int maxLost = getLostMaxFast(inputA2, inputB2);
        System.out.println((n - maxLost) + " " + minWins);
    }

    private static int getWonMaxFast(int[] A, int[] B) {
        int[] wins = new int[3];
        for (int i = 0; i < 3; i++) {
            int good = (i + 1) % 3;
            int add = Math.min(A[i], B[good]);
            wins[i] = add;
            A[i] -= add;
            B[good] -= add;
        }
        return wins[0] + wins[1] + wins[2];
    }

    private static int getLostMaxFast(int[] A, int[] B) {
        int[][] ways = {{0,2}, {1,0}, {2,1}, {0,0}, {1,1}, {2,2}};
        int[] indices = {0,1,2,3,4,5};
        List<int[]> perms = new ArrayList<>();
        permute(indices, 0, perms);
        int maxLost = 0;
        for (int[] perm : perms) {
            int[] ac = A.clone();
            int[] bc = B.clone();
            int lost = 0;
            for (int idx : perm) {
                int ca = ways[idx][0];
                int cb = ways[idx][1];
                int add = Math.min(ac[ca], bc[cb]);
                ac[ca] -= add;
                bc[cb] -= add;
                lost += add;
            }
            if (lost > maxLost) maxLost = lost;
        }
        return maxLost;
    }

    private static void permute(int[] arr, int start, List<int[]> result) {
        if (start == arr.length - 1) {
            result.add(arr.clone());
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            permute(arr, start + 1, result);
            swap(arr, start, i);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

