import java.util.*;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int turnNum = scanner.nextInt();
        scanner.nextLine(); // consume the newline

        String[] aliceInput = scanner.nextLine().split(" ");
        List<Integer> aliceChoices = Arrays.stream(aliceInput)
                                           .map(Integer::parseInt)
                                           .collect(Collectors.toList());

        String[] bobInput = scanner.nextLine().split(" ");
        List<Integer> bobChoices = Arrays.stream(bobInput)
                                         .map(Integer::parseInt)
                                         .collect(Collectors.toList());

        // Rotate Bob's choices (move first element to the end)
        int firstBob = bobChoices.remove(0);
        bobChoices.add(firstBob);

        int minWin = 0;
        int maxWin = 0;

        // Calculate the maximum number of rounds Alice can win
        for (int i = 0; i < aliceChoices.size(); i++) {
            maxWin += Math.min(aliceChoices.get(i), bobChoices.get(i));
        }

        // Calculate the minimum number of rounds Alice can win
        int maxBob = Collections.max(bobChoices);
        for (int i = 0; i < bobChoices.size(); i++) {
            int choice = bobChoices.get(i);
            if (choice == maxBob && choice + aliceChoices.get(i) > minWin) {
                minWin = choice + aliceChoices.get(i);
            }
        }

        int maxAlice = Collections.max(aliceChoices);
        for (int i = 0; i < aliceChoices.size(); i++) {
            int choice = aliceChoices.get(i);
            if (choice == maxAlice && choice + bobChoices.get(i) > minWin) {
                minWin = choice + bobChoices.get(i);
            }
        }

        minWin = minWin > turnNum ? minWin - turnNum : 0;

        System.out.println(minWin + " " + maxWin);

        scanner.close();
    }
}

import java.util.Scanner;

public class Solve {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // read round (not used)
        int round = scanner.nextInt();
        scanner.nextLine(); // consume newline

        // read first person's moves
        String[] firstLine = scanner.nextLine().split(" ");
        int[] first = new int[3];
        for (int i = 0; i < 3; i++) {
            first[i] = Integer.parseInt(firstLine[i]);
        }

        // read second person's moves
        String[] secondLine = scanner.nextLine().split(" ");
        int[] second = new int[3];
        for (int i = 0; i < 3; i++) {
            second[i] = Integer.parseInt(secondLine[i]);
        }

        // compute maximum wins
        int maxWin = 0;
        for (int i = 0; i < 3; i++) {
            maxWin += Math.min(first[i], second[(i + 1) % 3]);
        }

        // compute minimum wins using greedy reduction
        int[] firstCopy = first.clone();
        int[] sec = new int[4];
        sec[0] = second[2];
        sec[1] = second[0];
        sec[2] = second[1];
        sec[3] = second[2];

        for (int i = 0; i < 3; i++) {
            if (firstCopy[i] > 0) {
                int diff1 = Math.min(firstCopy[i], sec[i]);
                firstCopy[i] -= diff1;
                sec[i] -= diff1;
                if (firstCopy[i] > 0) {
                    int diff2 = Math.min(firstCopy[i], sec[i + 1]);
                    firstCopy[i] -= diff2;
                    sec[i + 1] -= diff2;
                }
            }
        }
        int minWin = firstCopy[0] + firstCopy[1] + firstCopy[2];

        // output result
        System.out.println(minWin + " " + maxWin);

        scanner.close();
    }
}

