import java.util.*;
import java.io.*;

public class Main {
    static BufferedReader br;
    static StringTokenizer st;
    static PrintWriter out;

    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens())
            st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    // Unused functions from original Python
    static final long MOD = 1000000007L;

    static long modpow(long a, long p) {
        long ans = 1;
        while (p > 0) {
            if ((p & 1) == 1) {
                ans = (ans * a) % MOD;
            }
            p >>= 1;
            a = (a * a) % MOD;
        }
        return ans;
    }

    static long fac_cal(int n) {
        long ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = (ans * i) % MOD;
        }
        return ans;
    }

    // Precomputed all permutations of [1,2,3,4,5,6]
    static List<int[]> perms = new ArrayList<>();

    static void generatePermutations(int[] arr, int idx) {
        if (idx == arr.length) {
            perms.add(arr.clone());
            return;
        }
        for (int i = idx; i < arr.length; i++) {
            swap(arr, idx, i);
            generatePermutations(arr, idx + 1);
            swap(arr, idx, i);
        }
    }

    static void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }

    static void solve() throws IOException {
        // Generate permutations once
        if (perms.isEmpty()) {
            int[] base = {1, 2, 3, 4, 5, 6};
            generatePermutations(base, 0);
        }

        // t = 1 (single test case)
        int n = nextInt();
        int a1 = nextInt(), a2 = nextInt(), a3 = nextInt();
        int b1 = nextInt(), b2 = nextInt(), b3 = nextInt();

        int mx = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        int temp = 0;

        for (int[] per : perms) {
            int ta1 = a1, ta2 = a2, ta3 = a3;
            int tb1 = b1, tb2 = b2, tb3 = b3;
            int tmx = 0;

            for (int el : per) {
                if (el == 1) {
                    int t1 = Math.min(ta1, tb1);
                    ta1 -= t1;
                    tb1 -= t1;
                    tmx += t1;
                } else if (el == 2) {
                    int t1 = Math.min(ta1, tb3);
                    ta1 -= t1;
                    tb3 -= t1;
                    tmx += t1;
                } else if (el == 3) {
                    int t1 = Math.min(ta2, tb2);
                    ta2 -= t1;
                    tb2 -= t1;
                    tmx += t1;
                } else if (el == 4) {
                    int t1 = Math.min(ta2, tb1);
                    ta2 -= t1;
                    tb1 -= t1;
                    tmx += t1;
                } else if (el == 5) {
                    int t1 = Math.min(ta3, tb3);
                    ta3 -= t1;
                    tb3 -= t1;
                    tmx += t1;
                } else if (el == 6) {
                    int t1 = Math.min(ta3, tb2);
                    ta3 -= t1;
                    tb2 -= t1;
                    tmx += t1;
                }
            }
            temp = Math.max(temp, tmx);
        }

        out.print((n - temp) + " ");
        out.println(mx);
    }

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        try {
            // Only one test case as in original
            solve();
        } finally {
            out.close();
            br.close();
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, rev;
        long cap;
        Edge(int to, int rev, long cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static class Dinic {
        private int n;
        private ArrayList<ArrayList<Edge>> graph;
        private int[] level;
        private int[] it;

        public Dinic(int n) {
            this.n = n;
            graph = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                graph.add(new ArrayList<>());
            }
            level = new int[n];
            it = new int[n];
        }

        public void addEdge(int from, int to, long cap) {
            graph.get(from).add(new Edge(to, graph.get(to).size(), cap));
            graph.get(to).add(new Edge(from, graph.get(from).size() - 1, 0));
        }

        private void bfs(int s) {
            Arrays.fill(level, -1);
            Deque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.addLast(s);
            while (!q.isEmpty()) {
                int v = q.removeFirst();
                for (Edge e : graph.get(v)) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.addLast(e.to);
                    }
                }
            }
        }

        private long dfs(int v, int t, long f) {
            if (v == t) return f;
            for (; it[v] < graph.get(v).size(); it[v]++) {
                Edge e = graph.get(v).get(it[v]);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        graph.get(e.to).get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        public long flow(int s, int t) {
            long flow = 0;
            final long INF = (long) 1e18;
            while (true) {
                bfs(s);
                if (level[t] < 0) break;
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, t, INF)) > 0) {
                    flow += f;
                }
            }
            return flow;
        }
    }

    private static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private static StringTokenizer st;

    private static int nextInt() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return Integer.parseInt(st.nextToken());
    }

    private static int[] list(int n) throws IOException {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public static void main(String[] args) throws IOException {
        int N = nextInt();
        int M = 3;
        int[] A = list(M);
        int[] B = list(M);

        long ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A[i], B[(i + 1) % M]);
        }

        Dinic dinic = new Dinic(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;
        for (int i = 0; i < M; i++) {
            dinic.addEdge(s, i, N);
            dinic.addEdge(M + i, t, B[i]);
            dinic.addEdge(i, M + i, A[i]);
            dinic.addEdge(i, M + (i - 1 + M) % M, A[i]);
        }
        long ans2 = N - dinic.flow(s, t);

        System.out.println(ans2 + " " + ans1);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.close();

        int size = 2 * n + 1;
        int[] c = new int[size];
        c[n] = 1;  // middle element

        for (int i = n - 1; i >= 1; i--) {
            // c[i] = 2*c[i+1] % m
            c[i] = (int)((2L * c[i+1]) % m);
            for (int j = 2; j <= n / i; j++) {
                // c[i] = (c[i] + c[i*j] - c[(i+1)*j]) % m
                long sum = (long)c[i] + c[i*j] - c[(i+1)*j];
                c[i] = (int)(sum % m);
                if (c[i] < 0) {
                    c[i] += m;
                }
            }
        }

        int result = ((c[1] - c[2]) % m + m) % m;
        System.out.println(result);
    }
}

