        DP[0] = 1;
        Cum[1] = 1;

        for (int i1 = 1; i1 < N; i1++) {
            int i2 = N - i1;
            long value = Cum[i1];
            for (int j = 2; j <= N; j++) {
                if (i2 * j > N) break;
                int idx1 = N - i2 * j + 1;
                int idx2 = N - i2 * j - j + 1;
                if (idx2 < 0) idx2 = 0;
                long temp = (value + Cum[idx1] - Cum[idx2]) % MOD;
                if (temp < 0) temp += MOD;
                value = temp;
            }
            Cum[i1 + 1] = (int)(((long)Cum[i1] + value) % MOD);
            DP[i1] = (int)value;
        }
        System.out.println(DP[N - 1]);
    }
}

