import java.util.*;

public class Main {
    static List<Integer> primes = new ArrayList<>();

    static {
        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) break;
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) primes.add(p);
        }
    }

    static Map<Integer, Integer> factor(int n) {
        Map<Integer, Integer> d = new HashMap<>();
        for (int p : primes) {
            if (p * p > n) break;
            if (n % p == 0) {
                int c = 0;
                while (n % p == 0) {
                    n /= p;
                    c++;
                }
                d.put(p, c);
            }
        }
        if (n > 1) d.put(n, 1);
        return d;
    }

    static List<Integer> factors(int n) {
        Map<Integer, Integer> d = factor(n);
        List<Integer> answer = new ArrayList<>();
        answer.add(1);
        for (Map.Entry<Integer, Integer> entry : d.entrySet()) {
            int p = entry.getKey();
            int exp = entry.getValue();
            List<Integer> a2 = new ArrayList<>();
            for (int x : answer) {
                long base = 1;
                for (int i = 0; i <= exp; i++) {
                    a2.add((int)(x * base));
                    base *= p;
                }
            }
            answer = a2;
        }
        return answer;
    }

    static long process(int n, int m) {
        long[] f = new long[n + 1];
        if (n >= 0) f[0] = 0;
        if (n >= 1) f[1] = 1;
        if (n >= 2) f[2] = 2;
        for (int i = 3; i <= n; i++) {
            long val = (2 * f[i - 1]) % m;
            List<Integer> divs = factors(i);
            for (int x : divs) {
                if (x >= 2 && x <= i) {
                    long add = (f[i / x] - f[(i - 1) / x]) % m;
                    val = (val + add + m) % m;
                }
            }
            f[i] = val % m;
        }
        return f[n];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        System.out.println(process(n, m));
        sc.close();
    }
}

