        Scanner scanner = new Scanner(System.in);
        int T = 1;
        final long M = 1000000007L;

        for (int t = 0; t < T; t++) {
            int P = scanner.nextInt();
            int K = scanner.nextInt();

            int[] k = new int[P];
            for (int x = 0; x < P; x++) {
                k[x] = (K * x) % P;
            }

            if (K == 0) {
                System.out.println(powMod(P, P - 1, M));
                continue;
            }
            if (K == 1) {
                System.out.println(powMod(P, P, M));
                continue;
            }

            int[] f = new int[P];
            int[] c = new int[P];
            long ans = 1L;

            for (int i = 0; i < P; i++) {
                if (f[i] != 0) continue;

                int cnt = 1;
                int u = i;
                f[u] = 1;
                while (f[k[u]] == 0) {
                    u = k[u];
                    f[u] = 1;
                    cnt++;
                }

                c[cnt]++;
            }

            for (int i = 2; i < P; i++) {
                if (c[i] != 0) {
                    long cnt = (long)i * c[i] + 1L;
                    ans = ans * powMod(cnt, c[i], M) % M;
                }
            }

            System.out.println(ans);
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1L;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % mod;
            }
            exp >>= 1L;
            base = (base * base) % mod;
        }
        return result;
    }
}

