import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        System.out.println(solve(p, k));
    }

    public static long solve(int p, int k) {
        final long MOD = 1000000007L;
        Set<Integer> used = new HashSet<>();
        int num = 0;
        for (int j = 0; j < p; j++) {
            if (!used.contains(j)) {
                num++;
                int i = j;
                while (!used.contains(i)) {
                    used.add(i);
                    i = (int)(((long)i * k) % p);
                }
            }
        }
        long exp = num - (k != 1 ? 1 : 0);
        return powMod(p, exp, MOD);
    }

    public static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

