import java.util.Scanner;

public class Main {
    private static long opow(long a, long b, long mod) {
        long ans = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                ans = (ans * a) % mod;
            }
            a = (a * a) % mod;
            b >>= 1;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        final long MOD = 1000000007L;
        long ans = 0L;
        if (k == 0) {
            ans = opow(p, p - 1, MOD);
        } else {
            for (int i = 1; i < p; i++) {
                if ((p - 1) % i == 0 && opow(k, i, p) == 1L) {
                    ans = opow(p, (p - 1) / i, MOD);
                    if (k == 1) {
                        ans = (ans * p) % MOD;
                    }
                    break;
                }
            }
        }
        System.out.println(ans);
        sc.close();
    }
}

