public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int P = sc.nextInt();
        int K = sc.nextInt();

        if (K == 0) {
            System.out.println(modPow(P, P - 1, MOD));
            return;
        }

        // compute k[x] = (K * x) % P
        int[] k = new int[P];
        for (int x = 0; x < P; x++) {
            long val = ((long) K) * x % P;
            k[x] = (int) val;
        }

        int[] f = new int[P];
        int[] c = new int[P];

        for (int i = 0; i < P; i++) {
            if (f[i] != 0) continue;

            int cnt = 1;
            int u = i;
            f[u] = 1;
            while (f[k[u]] == 0) {
                u = k[u];
                f[u] = 1;
                cnt++;
            }
            c[cnt]++;
        }

        long ans = 1;
        for (int i = 1; i < P; i++) {
            if (c[i] != 0) {
                long cnt = (long) i * c[i] + (i > 1 ? c[1] : 0);
                ans = ans * modPow(cnt, c[i], MOD) % MOD;
            }
        }

        System.out.println(ans);
    }

    // fast modular exponentiation
    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

