        // 2^b - 1
        if (b == 0) return BigInteger.ZERO;
        return BigInteger.ONE.shiftLeft(b).subtract(BigInteger.ONE);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] input = sc.nextLine().split(" ");
        int h = Integer.parseInt(input[0]);
        int n = Integer.parseInt(input[1]);
        BigInteger bigN = BigInteger.valueOf(n);
        BigInteger l = BigInteger.ONE;
        BigInteger r = BigInteger.valueOf(2).pow(h);
        int b = h;
        String dir = "L";
        BigInteger ans = BigInteger.ZERO;
        BigInteger two = BigInteger.TWO;

        for (int i = 0; i < h; i++) {
            BigInteger sum = l.add(r);
            BigInteger twoN = bigN.multiply(two);
            if (dir.equals("L")) {
                if (twoN.compareTo(sum) > 0) { // n > (l+r)/2
                    ans = ans.add(cnt_res(b)).add(BigInteger.ONE);
                    l = sum.divide(two).add(BigInteger.ONE);
                } else if (twoN.compareTo(sum) < 0) { // n < (l+r)/2
                    int parity = sum.testBit(0) ? 1 : 0; // 1 if odd
                    r = sum.divide(two).add(BigInteger.valueOf(parity)).subtract(BigInteger.ONE);
                    ans = ans.add(BigInteger.ONE);
                    dir = "R";
                }
            } else { // dir == "R"
                if (twoN.compareTo(sum) < 0) { // n < (l+r)/2
                    ans = ans.add(cnt_res(b)).add(BigInteger.ONE);
                    int parity = sum.testBit(0) ? 1 : 0;
                    r = sum.divide(two).add(BigInteger.valueOf(parity)).subtract(BigInteger.ONE);
                } else if (twoN.compareTo(sum) > 0) { // n > (l+r)/2
                    ans = ans.add(BigInteger.ONE);
                    l = sum.divide(two).add(BigInteger.ONE);
                    dir = "L";
                }
            }
            b--;
        }

        System.out.println(ans);
    }
}

