public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        long n = sc.nextLong();
        sc.close();

        long[] sl = new long[51];
        sl[0] = 1;
        for (int i = 1; i <= 50; i++) {
            sl[i] = sl[i-1] + (1L << i);
        }

        n += sl[h-1];
        long tn = n;
        List<Long> nl = new ArrayList<>();
        nl.add(tn);
        while (tn != 1) {
            tn /= 2;
            nl.add(tn);
        }

        long ans = 0;
        long cn = 1;
        boolean cp = false;

        while (cn != n) {
            List<Long> tnl = new ArrayList<>();
            for (int i = 0; i < h; i++) {
                tnl.add(cn);
                if (!cp) {
                    cn *= 2;
                } else {
                    cn = cn * 2 + 1;
                }
                cp = !cp;
            }
            tnl.add(cn);

            if (cn == n) {
                ans += h;
                break;
            }

            Collections.reverse(tnl);
            for (int i = 1; i <= h; i++) {
                if (nl.get(i).equals(tnl.get(i))) {
                    ans += sl[i-1] + h - i + 1;
                    h = i - 1;
                    cn = tnl.get(i-1);
                    if (cn == tnl.get(i) * 2) {
                        cn = tnl.get(i) * 2 + 1;
                        cp = false;
                    } else {
                        cn = tnl.get(i) * 2;
                        cp = true;
                    }
                    break;
                }
            }
        }

        System.out.println(ans);
    }
}

import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int h = in.nextInt();
        long n = in.nextLong();
        n -= 1; // convert to 0-indexed

        // Build binary string of length h with leading zeros
        StringBuilder sb = new StringBuilder(h);
        for (int i = h - 1; i >= 0; i--) {
            if ((n & (1L << i)) != 0) {
                sb.append('1');
            } else {
                sb.append('0');
            }
        }
        String nStr = sb.toString();

        // Build s string according to the rule
        StringBuilder s = new StringBuilder(h);
        for (int i = 0; i < h; i++) {
            if (i > 0 && nStr.charAt(i - 1) == '0') {
                // flip the bit
                s.append(nStr.charAt(i) == '0' ? '1' : '0');
            } else {
                s.append(nStr.charAt(i));
            }
        }
        String sStr = s.toString();

        // Compute the answer
        long ct = 0;
        for (int i = 0; i < h; i++) {
            ct++;
            if (sStr.charAt(i) == '1') {
                ct += (1L << (h - i)) - 1;
            }
        }
        System.out.println(ct);
    }
}

