        long ans = 0L;
        boolean f = false;
        for (int i = 0; i < h; i++) {
            char ch = N.charAt(i);
            char expected = f ? '0' : '1';
            if (ch != expected) {
                f = !f;
                ans += 1L;
            } else {
                ans += (1L << (h - i));
            }
        }
        System.out.println(ans);
    }
}

