public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int n = scanner.nextInt();
        h -= 1;
        n -= 1;
        int l = 0;
        int r = 2 << h;
        boolean ll = true;
        int ans = 0;
        int i = 0;
        while (r - l > 1) {
            int m = (l + r) / 2;
            if (ll == (n < m)) {
                ans += 1;
            } else {
                ans += 1 << (h - i + 1);
            }
            if (n < m) {
                r = m;
                ll = false;
            } else {
                l = m;
                ll = true;
            }
            i++;
        }
        System.out.println(ans);
        scanner.close();
    }
}

