public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();

        if (s.startsWith("dot") || s.startsWith("at") || s.endsWith("at") || s.endsWith("dot")) {
            if (s.startsWith("dot")) {
                String t = s.substring(3);
                String l = t.replace("dot", ".");
                int b = l.indexOf("at");
