                } else {
                    s = q;
                }
            }
            if (s.startsWith("at")) {
                String t = s.substring(2);
                String l = t.replace("dot", ".");
                int b = l.indexOf("at");
                String o = replaceAt(l, b);
                String q = "at" + o;
                if (q.endsWith(".")) {
                    s = q.substring(0, q.length() - 1) + "dot";
                } else if (q.endsWith("@")) {
                    s = q.substring(0, q.length() - 1) + "at";
                } else {
                    s = q;
                }
            }
            if (s.endsWith("dot") && !s.startsWith("dot") && !s.startsWith("at")) {
                String t = s.substring(0, s.length() - 3);
                String l = t.replace("dot", ".");
                int b = l.indexOf("at");
                String q = replaceAt(l, b);
                s = q + "dot";
            }
            if (s.endsWith("at") && !s.startsWith("dot") && !s.startsWith("at")) {
                String t = s.substring(0, s.length() - 2);
                String l = t.replace("dot", ".");
                int b = l.indexOf("at");
                String q = replaceAt(l, b);
                s = q + "at";
            }
            System.out.println(s);
        } else {
            String l = s.replace("dot", ".");
            int b = l.indexOf("at");
            String q = replaceAt(l, b);
            System.out.println(q);
        }
    }

    private static String replaceAt(String l, int b) {
        if (b == -1) {
            if (l.length() == 0) {
                return "@";
            }
            return l.substring(0, l.length() - 1) + "@" + l.substring(1);
