        Scanner scanner = new Scanner(System.in);
        String string = scanner.nextLine();
        scanner.close();

        // While "dot" occurs in the substring from index 1 to length-1 (exclusive)
        while (true) {
            if (string.length() < 3) break; // No interior possible
            String inner = string.substring(1, string.length() - 1);
            int idx = inner.indexOf("dot");
            if (idx == -1) {
                break;
            }
            int actualIndex = 1 + idx; // index of 'd' in the original string
            string = string.substring(0, actualIndex) + "." + string.substring(actualIndex + 3);
        }

        // Replace "at" once in the substring from index 1 to end (exclude first character)
        if (string.length() > 1) {
            String inner = string.substring(1);
            int idx = inner.indexOf("at");
            if (idx != -1) {
                int actualIndex = 1 + idx;
                string = string.substring(0, actualIndex) + "@" + string.substring(actualIndex + 2);
            }
        }

        System.out.println(string);
    }
}

