    private static int largestLessThan(List<Integer> list, int key) {
        // returns largest element in list that is < key, or 0 if none.
        int lo = 0;
        int hi = list.size() - 1;
        int ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            int midVal = list.get(mid);
            if (midVal < key) {
                ans = midVal;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
}

