            System.arraycopy(data, 0, this.data, size, data.length);
            for (int i = size - 1; i > 0; i--) {
                this.data[i] = func.apply(this.data[i + i], this.data[i + i + 1]);
            }
        }

        public void delete(int idx) {
            set(idx, _default);
        }

        public int get(int idx) {
            return data[idx + _size];
        }

        public void set(int idx, int value) {
            idx += _size;
            data[idx] = value;
            idx >>= 1;
            while (idx > 0) {
                data[idx] = _func.apply(data[2 * idx], data[2 * idx + 1]);
                idx >>= 1;
            }
        }

        public int query(int start, int stop) {
            if (start == stop) return get(start);
            stop++;
            start += _size;
            stop += _size;
            int res = _default;
            while (start < stop) {
                if ((start & 1) == 1) {
                    res = _func.apply(res, data[start]);
                    start++;
                }
                if ((stop & 1) == 1) {
                    stop--;
                    res = _func.apply(res, data[stop]);
                }
                start >>= 1;
                stop >>= 1;
            }
            return res;
        }

        @FunctionalInterface
        interface BinaryOperator {
            int apply(int a, int b);
        }
    }

    static class Factorial {
        private int MOD;
        private ArrayList<Long> factorials;
        private ArrayList<Long> invModulos;
        private ArrayList<Long> invFactorial_;

        public Factorial(int MOD) {
            this.MOD = MOD;
            factorials = new ArrayList<>();
            factorials.add(1L);
            factorials.add(1L);
            invModulos = new ArrayList<>();
            invModulos.add(0L);
            invModulos.add(1L);
            invFactorial_ = new ArrayList<>();
            invFactorial_.add(1L);
            invFactorial_.add(1L);
        }

        public long calc(int n) {
            if (n <= -1) {
                System.out.println("Invalid argument to calculate n!");
                System.out.println("n must be non-negative value. But the argument was " + n);
                System.exit(0);
            }
            if (n < factorials.size()) {
                return factorials.get(n);
            }
            long[] nextArr = new long[n - factorials.size() + 1];
            int initialI = factorials.size();
            long prev = factorials.get(factorials.size() - 1);
            int m = MOD;
            for (int i = initialI; i <= n; i++) {
                prev = (prev * i) % m;
                nextArr[i - initialI] = prev;
            }
            for (long val : nextArr) {
                factorials.add(val);
            }
            return factorials.get(n);
        }

        public long inv(int n) {
            if (n <= -1) {
                System.out.println("Invalid argument to calculate n^(-1)");
                System.out.println("n must be non-negative value. But the argument was " + n);
                System.exit(0);
            }
            int p = MOD;
            int pi = n % p;
            if (pi < invModulos.size()) {
                return invModulos.get(pi);
            }
            int initialI = invModulos.size();
            for (int i = initialI; i <= Math.min(p, n); i++) {
                long next = (-invModulos.get(p % i) * (p / i)) % p;
                if (next < 0) next += p;
                invModulos.add(next);
            }
            return invModulos.get(pi);
        }

        public long invFactorial(int n) {
            if (n <= -1) {
                System.out.println("Invalid argument to calculate (n^(-1))!");
                System.out.println("n must be non-negative value. But the argument was " + n);
                System.exit(0);
            }
            if (n < invFactorial_.size()) {
                return invFactorial_.get(n);
            }
            inv(n); // ensure n^-1 is calculated
            long[] nextArr = new long[n - invFactorial_.size() + 1];
            int initialI = invFactorial_.size();
            long prev = invFactorial_.get(invFactorial_.size() - 1);
            int p = MOD;
            for (int i = initialI; i <= n; i++) {
                prev = (prev * invModulos.get(i % p)) % p;
                nextArr[i - initialI] = prev;
            }
            for (long val : nextArr) {
                invFactorial_.add(val);
            }
            return invFactorial_.get(n);
        }
    }

    static class Combination {
        private int MOD;
        private Factorial factorial;

        public Combination(int MOD) {
            this.MOD = MOD;
            this.factorial = new Factorial(MOD);
        }

        public long ncr(int n, int k) {
            if (k < 0 || n < k) return 0;
            if (k > n - k) k = n - k;
            Factorial f = factorial;
            long res = f.calc(n);
            res = (res * f.invFactorial(Math.max(n - k, k))) % MOD;
            res = (res * f.invFactorial(Math.min(k, n - k))) % MOD;
            return res;
        }
    }

    public static long powm(long a, long n, long m) {
        if (a == 1 || n == 0) return 1;
        if (n % 2 == 0) {
            long s = powm(a, n / 2, m);
            return (s * s) % m;
        } else {
            return (a * powm(a, n - 1, m)) % m;
        }
    }

    public static List<Integer> sortList(List<Integer> list1, List<Integer> list2) {
        List<int[]> pairs = new ArrayList<>();
        for (int i = 0; i < list1.size(); i++) {
            pairs.add(new int[]{list2.get(i), list1.get(i)});
        }
        pairs.sort(Comparator.comparingInt(a -> a[0]));
        List<Integer> res = new ArrayList<>();
        for (int[] p : pairs) {
            res.add(p[1]);
        }
        return res;
    }

    public static int product(List<Integer> l) {
        int por = 1;
        for (int val : l) por *= val;
        return por;
    }

    public static int binarySearchCount(List<Integer> arr, int n, int key) {
        int left = 0;
        int right = n - 1;
        int count = 0;
        while (left <= right) {
            int mid = (right + left) / 2;
            if (arr.get(mid) <= key) {
                count = mid + 1;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return count;
    }

    public static int countdig(long n) {
        int c = 0;
        while (n > 0) {
            n /= 10;
            c++;
        }
        return c;
    }

    public static int countGreater(List<Integer> arr, int n, int k) {
        int l = 0;
        int r = n - 1;
        int leftGreater = n;
        while (l <= r) {
            int m = l + (r - l) / 2;
            if (arr.get(m) >= k) {
                leftGreater = m;
                r = m - 1;
            } else {
                l = m + 1;
            }
        }
        return n - leftGreater;
    }

