import java.util.*;
import java.util.stream.*;

public class Main {
    static int n, mod;
    static Map<Long, Integer>[][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();
        memo = new HashMap[n+1][2];
        for (int i = 0; i <= n; i++) {
            memo[i][0] = new HashMap<>();
            memo[i][1] = new HashMap<>();
        }
        int ans = solve(n, 0, 1) % mod;
        System.out.println(ans);
        sc.close();
    }

    static int invnum(int[] seq) {
        int N = seq.length;
        int res = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i+1; j < N; j++) {
                if (seq[i] > seq[j]) {
                    res++;
                }
            }
        }
        return res;
    }

    static int naive(int N, int k, boolean flag) {
        int res = 0;
        int[] perm = IntStream.range(0, N).toArray();
        List<int[]> perms = new ArrayList<>();
        permutation(perm, 0, perms);
        for (int[] p : perms) {
            for (int[] q : perms) {
                boolean condition = (comparePerm(p, q) < 0) || !flag;
                if (condition && (invnum(p) - invnum(q) > k)) {
                    res++;
                }
            }
        }
        return res;
    }

    static boolean nextPermutation(int[] arr) {
        int i = arr.length - 2;
        while (i >= 0 && arr[i] >= arr[i+1]) i--;
        if (i < 0) return false;
        int j = arr.length - 1;
        while (arr[j] <= arr[i]) j--;
        swap(arr, i, j);
        reverse(arr, i+1, arr.length-1);
        return true;
    }

    static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    static void reverse(int[] arr, int l, int r) {
        while (l < r) {
            swap(arr, l, r);
            l++;
            r--;
        }
    }

    static int comparePerm(int[] a, int[] b) {
        for (int i = 0; i < a.length; i++) {
            if (a[i] != b[i]) return a[i] - b[i];
        }
        return 0;
    }

    static void permutation(int[] arr, int start, List<int[]> result) {
        if (start == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            permutation(arr, start+1, result);
            swap(arr, start, i);
        }
    }

    static int solve(int N, int k, int flag) {
        Long key = (long)k;
        if (memo[N][flag].containsKey(key)) {
            return memo[N][flag].get(key);
        }
        if (N == 1) {
            int res;
            if (flag == 1) {
                res = 0;
            } else {
                if (k < 0) {
                    res = 1;
                } else {
                    res = 0;
                }
            }
            memo[N][flag].put(key, res);
            return res;
        }
        int invnum_INF = N * (N-1) / 2;
        if (k < -invnum_INF - 1) {
            int res = solve(N, -invnum_INF - 1, flag);
            memo[N][flag].put(key, res);
            return res;
        }
        if (k >= invnum_INF) {
            memo[N][flag].put(key, 0);
            return 0;
        }
        long res = 0;
        for (int delta = -N+1; delta < N; delta++) {
            if (flag == 1 && delta > 0) continue;
            int wt = Math.min(N - delta, delta + N);
            res += (long)solve(N-1, k-delta, (delta == 0 && flag == 1) ? 1 : 0) * wt;
            res %= mod;
        }
        memo[N][flag].put(key, (int)(res % mod));
        return (int)(res % mod);
    }
}

