    static long solve(long n, long mod) {
        if (n <= 3) {
            return 0;
        } else {
            long lastAns = 17;
            long ans = 17;
            long size = (n-1)*(n-2)/2 + 1;
            int inv = 0;
            // record: 2 rows, each of size+1
            long[][] record = new long[2][(int)size+1];
            // Python: record[0][0:4]=[1,2,2,1]
            record[0][0] = 1;
            record[0][1] = 2;
            record[0][2] = 2;
            record[0][3] = 1;

            for (long m = 4; m < n; m++) {
                long tpSize = m * (m-1) / 2;
                ans = (m + 1) * lastAns;
                long tp = 0;
                int nextInv = inv ^ 1;
                // first loop: i from 0 to m-1
                for (int i = 0; i < m; i++) {
                    tp += record[inv][i];
                    record[nextInv][i] = tp % mod;
                }
                // second loop: i from m to tpSize/2
                long half = tpSize / 2;
                for (int i = (int)m; i <= half; i++) {
                    tp += record[inv][i];
                    tp -= record[inv][(int)(i - m)];
                    record[nextInv][i] = tp % mod;
                }
                // third: mirror
                for (int i = 0; i <= half; i++) {
                    record[nextInv][(int)(tpSize - i)] = record[nextInv][i];
                }
                long total = 0;
                long tpSizeMinus1 = tpSize - 1;
                for (long i = 0; i < tpSizeMinus1; i++) {
                    long tp2 = 0;
                    // inner loop j from max(1, -tpSize + i + m + 2) to m
                    long start = Math.max(1, -tpSize + i + m + 2);
                    for (long j = start; j <= m; j++) {
                        long index = m + 2 - j + i;
                        tp2 += j * record[nextInv][(int)index];
                    }
