                    total %= mod;
                    tp2 %= mod;
                    tp2 = (tp2 * total) % mod;
                    ans = (ans + tp2) % mod;
                }
                lastAns = ans;
                inv = nextInv;
            }
            return ans % mod;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long mod = sc.nextLong();
        System.out.println(solve(n, mod));
    }
