            if (h == 0) {
                value = BigInteger.ZERO;
            } else {
                BigInteger sum = BigInteger.ZERO;
                for (int i = 0; i < n; i++) {
                    sum = sum.add(go(i, h - 1).multiply(go(n - 1 - i, h - 1)));
                }
                value = sum;
            }
        }
        memo.put(key, value);
        return value;
    }
}

