import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    static BigInteger[][] dp;
    static int n;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int h = sc.nextInt();
        dp = new BigInteger[n+1][n+1];
        // initialize dp table with base cases and -1 for unknown
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = BigInteger.ONE;
                } else if (i == 0 || j == 0) {
                    dp[i][j] = BigInteger.ZERO;
                } else {
                    dp[i][j] = BigInteger.valueOf(-1);
                }
            }
        }
        // fill all entries
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                t(i, j);
            }
        }
        BigInteger ans = BigInteger.ZERO;
        for (int i = h; i <= n; i++) {
            ans = ans.add(dp[n][i]);
        }
        System.out.println(ans);
    }

    static BigInteger t(int n_val, int h_val) {
        // if already computed, return value
        if (!dp[n_val][h_val].equals(BigInteger.valueOf(-1))) {
            return dp[n_val][h_val];
        }
        // compute sum from m=1 to n_val
        BigInteger sum = BigInteger.ZERO;
        for (int m = 1; m <= n_val; m++) {
            // first part: t(m-1, h-1) * sum_{i=0}^{h-1} t(n-m, i)
            BigInteger term1 = t(m - 1, h_val - 1);
            BigInteger inner1 = BigInteger.ZERO;
            for (int i = 0; i < h_val; i++) {
                inner1 = inner1.add(t(n_val - m, i));
            }
            BigInteger part1 = term1.multiply(inner1);
            // second part: t(n-m, h-1) * sum_{i=0}^{h-2} t(m-1, i)
            BigInteger term2 = t(n_val - m, h_val - 1);
            BigInteger inner2 = BigInteger.ZERO;
            for (int i = 0; i < h_val - 1; i++) {
                inner2 = inner2.add(t(m - 1, i));
            }
            BigInteger part2 = term2.multiply(inner2);
            sum = sum.add(part1).add(part2);
        }
        dp[n_val][h_val] = sum;
        return sum;
    }
}

