import java.math.BigInteger;
import java.util.*;

public class Main {
    private static Map<Long, BigInteger> tab1 = new HashMap<>();
    private static Map<String, BigInteger> tab2 = new HashMap<>();

    private static BigInteger num1(int n) {
        if (n < 0) return BigInteger.ZERO;
        if (n < 2) return BigInteger.ONE;
        Long key = (long) n;
        if (tab1.containsKey(key)) return tab1.get(key);
        BigInteger r = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            r = r.add(num1(i).multiply(num1(n - 1 - i)));
        }
        tab1.put(key, r);
        return r;
    }

    private static BigInteger num2(int n, int h) {
        if (n < 0 || h <= 0) return BigInteger.ZERO;
        // Check n >= 2^(h-1)
        if (h >= 1) {
            BigInteger pow = BigInteger.ONE.shiftLeft(h - 1);
            if (BigInteger.valueOf(n).compareTo(pow) >= 0) return BigInteger.ZERO;
        }
        if (n < 2) return BigInteger.ONE;
        if (n < h) return num1(n);
        String key = n + "," + h;
        if (tab2.containsKey(key)) return tab2.get(key);
        BigInteger r = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            r = r.add(num2(i, h - 1).multiply(num2(n - 1 - i, h - 1)));
        }
        tab2.put(key, r);
        return r;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        BigInteger result = num1(n).subtract(num2(n, h));
